package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.BeanProperty;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDateFormat;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class DateTimeSerializerBase_createContextual_TriageGen0Test {

    private SerializerProvider serializers;
    private BeanProperty property;
    private TestDateTimeSerializer serializer;

    // Concrete implementation of the abstract class for testing
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<java.util.Date> {
        private final Boolean useTimestamp;
        private final DateFormat customFormat;

        protected TestDateTimeSerializer(Class<java.util.Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
            this.useTimestamp = useTimestamp;
            this.customFormat = customFormat;
        }

        @Override
        public JsonSerializer<?> withFormat(Boolean useTimestamp, DateFormat customFormat) {
            return new TestDateTimeSerializer(java.util.Date.class, useTimestamp, customFormat);
        }

        @Override
        public void serialize(java.util.Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) throws java.io.IOException {
        }

        @Override
        public boolean isEmpty(java.util.Date value) {
            return value == null;
        }

        @Override
        public boolean isEmpty(SerializerProvider serializers, java.util.Date value) {
            return value == null;
        }

        @Override
        protected long _timestamp(java.util.Date value) {
            return value == null ? 0L : value.getTime();
        }

        @Override
        public JsonNode getSchema(SerializerProvider serializers, JavaType typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(JsonFormatVisitorWrapper visitor, JavaType typeHint) throws JsonMappingException {
        }

        @Override
        protected boolean _asTimestamp(SerializerProvider serializers) {
            return useTimestamp != null && useTimestamp;
        }

        @Override
        protected void _acceptJsonFormatVisitor(JsonFormatVisitorWrapper visitor, JavaType typeHint, boolean asNumber) throws JsonMappingException {
        }

        // Mocking the protected method findFormatOverrides which is part of the base class logic
        // In a real Jackson environment, this is provided by the context. 
        // Since we are testing the logic inside createContextual, we need to control the outcome.
        // However, findFormatOverrides is protected. We will override it in our test subclass.
        private JsonFormat.Value mockFormatValue;

        @Override
        protected JsonFormat.Value findFormatOverrides(SerializerProvider serializers, BeanProperty property, JavaType handledType) {
            return mockFormatValue;
        }

        public void setMockFormatValue(JsonFormat.Value value) {
            this.mockFormatValue = value;
        }
    }

    @Before
    public void setUp() {
        serializers = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        serializer = new TestDateTimeSerializer(java.util.Date.class, false, null);

        when(serializers.getLocale()).thenReturn(Locale.US);
        when(serializers.getTimeZone()).thenReturn(TimeZone.getTimeZone("UTC"));
    }

    @Test
    public void testCreateContextual_PropertyNull() throws JsonMappingException {
        JsonSerializer<?> result = serializer.createContextual(serializers, null);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NoFormatOverrides() throws JsonMappingException {
        serializer.setMockFormatValue(null);
        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NumericShape() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.NUMBER_INT);
        serializer.setMockFormatValue(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertNotSame(serializer, result);
        assertTrue(result instanceof TestDateTimeSerializer);
        // Check if it returns a new instance with timestamp true
        // Since we can't easily inspect private fields of the base class, 
        // we rely on the logic flow and the fact that withFormat was called.
    }

    @Test
    public void testCreateContextual_StringShapeWithCustomPattern() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(true);
        when(format.getPattern()).thenReturn("yyyy-MM-dd");
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        serializer.setMockFormatValue(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertNotSame(serializer, result);
        // Verification of internal DateFormat is hard via reflection, 
        // but we ensure the code path completes without exception.
    }

    @Test
    public void testCreateContextual_HasLocaleAndTimeZone() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.FRANCE);
        when(format.hasTimeZone()).thenReturn(true);
        when(format.getTimeZone()).thenReturn(TimeZone.getTimeZone("GMT"));
        serializer.setMockFormatValue(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertNotSame(serializer, result);
    }

    @Test
    public void testCreateContextual_DefaultIsoFormat() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        // Trigger the (shape == STRING) condition
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        // Force false for pattern/locale/tz to hit the default branch in the ternary
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        serializer.setMockFormatValue(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertNotSame(serializer, result);
    }

    @Test
    public void testCreateContextual_Fallthrough() throws JsonMappingException {
        // To reach the final 'return this' (the "Otherwise" block), 
        // we need shape to NOT be numeric AND NOT (STRING OR pattern OR locale OR tz)
        // However, the logic is: if (shape == STRING || pattern || locale || tz)
        // So we need a shape that is not STRING and not numeric, and no other flags.

        JsonFormat.Value format = mock(JsonFormat.Value.class);
        // Shape.OBJECT is not numeric and not STRING
        when(format.getShape()).thenReturn(JsonFormat.Shape.OBJECT);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        serializer.setMockFormatValue(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertSame(serializer, result);
    }
}
